import OpenAI from "openai";
import Anthropic from "@anthropic-ai/sdk";
import { GoogleGenerativeAI } from "@google/generative-ai";

export type Provider = "openai" | "anthropic" | "gemini";

export interface ChatMessage {
  role: "system" | "user" | "assistant";
  content: string;
}

export interface ChatOptions {
  provider: Provider;
  model?: string;
  messages: ChatMessage[];
  temperature?: number;
}

const openai = process.env.OPENAI_API_KEY
  ? new OpenAI({ apiKey: process.env.OPENAI_API_KEY })
  : null;
const anthropic = process.env.ANTHROPIC_API_KEY
  ? new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY })
  : null;
const gemini = process.env.GEMINI_API_KEY
  ? new GoogleGenerativeAI(process.env.GEMINI_API_KEY)
  : null;

export async function chat(opts: ChatOptions): Promise<string> {
  if (opts.provider === "openai") {
    if (!openai) throw new Error("OPENAI_API_KEY not set");
    const r = await openai.chat.completions.create({
      model: opts.model ?? "gpt-4o-mini",
      messages: opts.messages,
      temperature: opts.temperature,
    });
    return r.choices[0]?.message?.content ?? "";
  }
  if (opts.provider === "anthropic") {
    if (!anthropic) throw new Error("ANTHROPIC_API_KEY not set");
    const system = opts.messages.find((m) => m.role === "system")?.content;
    const rest = opts.messages.filter((m) => m.role !== "system");
    const r = await anthropic.messages.create({
      model: opts.model ?? "claude-3-5-sonnet-20241022",
      system,
      max_tokens: 4096,
      messages: rest.map((m) => ({ role: m.role as "user" | "assistant", content: m.content })),
      temperature: opts.temperature,
    });
    const block = r.content[0];
    return block && block.type === "text" ? block.text : "";
  }
  if (opts.provider === "gemini") {
    if (!gemini) throw new Error("GEMINI_API_KEY not set");
    const model = gemini.getGenerativeModel({ model: opts.model ?? "gemini-1.5-flash" });
    const prompt = opts.messages.map((m) => `${m.role}: ${m.content}`).join("\n\n");
    const r = await model.generateContent(prompt);
    return r.response.text();
  }
  throw new Error(`Unknown provider: ${opts.provider as string}`);
}

postInstallNotes:
Set whichever API keys you plan to use — the wrapper will throw at call time if the chosen provider's key is missing.

```ts
import { chat } from "./lib/ai";
const answer = await chat({ provider: "openai", messages: [{ role: "user", content: "Hello" }] });
```
